/**
 * `sbom.cdx.json` — CycloneDX from the lockfile (12 §1.1, F11).
 *
 * **From the lockfile, not from the installed tree**, and that is the whole design. An SBOM
 * generated by walking `node_modules` describes the machine that ran the build; one
 * generated from `pnpm-lock.yaml` describes what the *recipe* resolves to, which is the
 * thing a second builder reproduces and an auditor compares against. If the two disagree,
 * the install was not `--frozen-lockfile` and the release is not reproducible — so reading
 * the tree would paper over exactly the failure the SBOM exists to expose.
 *
 * The lockfile is parsed with a targeted reader rather than a YAML dependency, for two
 * reasons that both matter more than convenience: an SBOM generator that pulls in a parser
 * adds a component to the very supply chain it is describing, and `app/` deliberately keeps
 * a small dependency tree (10 §10.1). The reader is strict — an unrecognised lockfile
 * version or a `packages:` section it cannot parse is an error, never an empty component
 * list, because an SBOM listing nothing is indistinguishable from a clean one.
 */

export class SbomError extends Error {
  constructor(message) {
    super(message);
    this.name = 'SbomError';
  }
}

const SUPPORTED_LOCKFILE_VERSIONS = new Set(['9.0']);

/**
 * `'@scope/name@1.2.3'` → `{ name: '@scope/name', version: '1.2.3' }`.
 *
 * Split on the **last** `@` so scoped names survive; refuse a key with no version, since a
 * component with no version pins nothing and would sit in the SBOM looking accounted for.
 */
export function splitPackageKey(key) {
  // The peer suffix is stripped **first**, and that ordering is the whole subtlety: a
  // peer-resolution suffix contains scoped package names of its own, so
  // `vite@8.1.4(@types/node@20.0.0)` split on its last `@` yields the name
  // `vite@8.1.4(@types/node` — a component that is in no registry and pins nothing. The
  // suffix is context about *how* a component was resolved, not part of its identity.
  const suffix = key.indexOf('(');
  const identity = suffix === -1 ? key : key.slice(0, suffix);
  const at = identity.lastIndexOf('@');
  if (at <= 0) throw new SbomError(`lockfile package key has no version: ${key}`);
  const name = identity.slice(0, at);
  const version = identity.slice(at + 1);
  if (!name || !version) throw new SbomError(`lockfile package key is malformed: ${key}`);
  return { name, version };
}

export function parseLockfile(text) {
  const versionMatch = /^lockfileVersion:\s*'?([0-9.]+)'?\s*$/m.exec(text);
  if (!versionMatch) throw new SbomError('lockfile declares no lockfileVersion');
  if (!SUPPORTED_LOCKFILE_VERSIONS.has(versionMatch[1])) {
    throw new SbomError(
      `lockfileVersion ${versionMatch[1]} is not one this reader has been checked against ` +
        `(${[...SUPPORTED_LOCKFILE_VERSIONS].join(', ')}); refusing to emit an SBOM it may ` +
        'have parsed only partly',
    );
  }
  const packagesAt = text.indexOf('\npackages:\n');
  if (packagesAt === -1) throw new SbomError('lockfile has no packages: section');
  const section = text.slice(packagesAt);
  const components = new Map();
  // The key charset must admit `:` — tarball and git-URL dependencies are recorded as
  // `pkg@https://…` and `pkg@github:owner/repo#sha`, and an earlier charset that excluded
  // the colon skipped exactly those. Skipping is the dangerous direction here: with other
  // packages present the "parsed nothing" check still passes, so the SBOM ships silently
  // missing the least conventional and most audit-relevant dependencies in the tree. The
  // key is therefore taken up to the final `:` of the line.
  const entry = /^ {2}'?(\S.*?)'?:\s*$/gm;
  let integrityFor = null;
  for (const line of section.split('\n')) {
    entry.lastIndex = 0;
    const match = entry.exec(line);
    if (match) {
      const { name, version } = splitPackageKey(match[1]);
      integrityFor = `${name}@${version}`;
      if (!components.has(integrityFor)) components.set(integrityFor, { name, version, integrity: null });
      continue;
    }
    const resolution = /^\s{4}resolution:\s*\{integrity:\s*([^,}]+)/.exec(line);
    if (resolution && integrityFor) {
      const component = components.get(integrityFor);
      if (component && component.integrity === null) component.integrity = resolution[1].trim();
    }
  }
  if (components.size === 0) {
    throw new SbomError('lockfile packages: section yielded no components; the format moved');
  }
  return [...components.values()].sort((a, b) =>
    a.name === b.name ? (a.version < b.version ? -1 : 1) : a.name < b.name ? -1 : 1,
  );
}

/** `sha512-<base64>` → CycloneDX `{alg, content}` with hex content. */
function cycloneHash(integrity) {
  if (!integrity) return [];
  const [algorithm, encoded] = integrity.split('-');
  const alg = { sha512: 'SHA-512', sha256: 'SHA-256', sha384: 'SHA-384', sha1: 'SHA-1' }[algorithm];
  if (!alg || !encoded) return [];
  return [{ alg, content: Buffer.from(encoded, 'base64').toString('hex') }];
}

/**
 * A CycloneDX 1.6 document with **no timestamp and no serial number**.
 *
 * Both are conventional and both would be nondeterministic, which would make the SBOM the
 * one file in the tree that differs between two environments building the same commit —
 * defeating 12 §1.1's byte-identical requirement for the sake of metadata nobody verifies.
 * The build's identity is carried by `release.json`'s source commit and recipe digest,
 * which are facts about the build rather than about the clock.
 */
export function buildSbom(components, { name, version }) {
  return {
    bomFormat: 'CycloneDX',
    specVersion: '1.6',
    version: 1,
    metadata: {
      component: { type: 'application', 'bom-ref': `${name}@${version}`, name, version },
      properties: [
        {
          name: 'bleavit:determinism',
          value:
            'no timestamp and no serialNumber: both are conventional, both are ' +
            'nondeterministic, and 12 §1.1 requires two environments to produce a ' +
            'byte-identical tree',
        },
      ],
    },
    components: components.map((component) => ({
      type: 'library',
      'bom-ref': `pkg:npm/${component.name}@${component.version}`,
      name: component.name,
      version: component.version,
      purl: `pkg:npm/${component.name}@${component.version}`,
      hashes: cycloneHash(component.integrity),
    })),
  };
}
